#include "codegen_internal.h"

void cg_print_builtin(Ctx* ctx,
                      FILE* out,
                      const CgPlacement* placement,
                      IrFunction* fn,
                      IrInstruction* inst) {
  ctx->cg_state.builtin_label_id++;
  switch (inst->operands.call.type) {
    case IR_FX_PRINT:
    case IR_FX_READ_INT:
    case IR_FX_READ_DOUBLE:
    case IR_FX_READ_BOOL:
    case IR_FX_READ_LINE:
      cg_print_io(ctx, out, placement, fn, inst);
      break;
    case IR_FX_TO_STR:
      cg_print_conversion(ctx, out, placement, fn, inst);
      break;
    case IR_FX_ORD:
    case IR_FX_STR_SUB:
    case IR_FX_STR_LEN:
    case IR_FX_TO_INT:
    case IR_FX_CHR:
      cg_print_string_builtin(ctx, out, placement, fn, inst);
      break;
    default:
      break;
  }
}
